/* Banque de questions — TAA (Types algébriques abstraits), cours.
   Source : fiches de synthèse du cours (types abstraits, listes, piles, files, ensembles) et types abstraits
   du Moodle de la promo 2031 (liste récursive, liste itérative, pile, file, ensembles, Vecteur, Booléen).
   Les ids « taa-cN-xx » renvoient au chapitre N du cours (taa/cours-N-….html) et servent aussi aux
   vérifications de fin de section. Les réponses des questions de calcul ont été recalculées avec un modèle
   des types (pile, file, listes, ensembles) et avec les axiomes appliqués terme à terme. */
(function () {
  var B = window.QCM_BANK = window.QCM_BANK || [];
  var T = window.QCM_TOPICS = window.QCM_TOPICS || {};
  T['taa-signature'] = 'Signature et vocabulaire';
  T['taa-hierarchie'] = 'Types et opérations : la hiérarchie';
  T['taa-precond'] = 'Préconditions';
  T['taa-axiomes'] = 'Axiomes';
  T['taa-liste-rec'] = 'Listes récursives';
  T['taa-liste-iter'] = 'Listes itératives';
  T['taa-piles'] = 'Piles';
  T['taa-files'] = 'Files';
  T['taa-ensembles'] = 'Ensembles et multi-ensembles';

  var C1 = 'taa/cours-1-types.html', C2 = 'taa/cours-2-listes.html', C3 = 'taa/cours-3-piles-files.html';
  /* bloc de spécification (assets/js/spec.js) : une ligne par argument */
  function spec() { return { code: Array.prototype.slice.call(arguments).join('\n') }; }

  var COMPTEUR = spec(
    'types',
    '    compteur',
    'utilise',
    '    entier, booléen',
    'opérations',
    '    nouveau : → compteur',
    '    incr    : compteur → compteur',
    '    raz     : compteur → compteur',
    '    valeur  : compteur → entier',
    '    estnul  : compteur → booléen');
  var VECT_IJ = spec(
    'axiomes',
    '    borneinf(v) ≤ i ≤ bornesup(v)',
    '        ⇒ estinitialisé(modifième(v, i, e), i) = vrai',
    '    borneinf(v) ≤ i ≤ bornesup(v) & borneinf(v) ≤ j ≤ bornesup(v)',
    '        ⇒ estinitialisé(modifième(v, i, e), j) = estinitialisé(v, j)');
  var CONCAT = spec(
    'opérations',
    '    concaténer : liste × liste → liste',
    'axiomes',
    '    concaténer(listevide, λ2) = λ2',
    '    concaténer(cons(e, λ), λ2) = cons(e, concaténer(λ, λ2))',
    'avec',
    '    liste λ, λ2 ; élément e');
  var PRESENT = spec(
    'opérations',
    '    est-présent : élément × liste → booléen',
    'axiomes',
    '    est-présent(e, listevide) = faux',
    '    e = e′ ⇒ est-présent(e, cons(e′, λ)) = vrai',
    '    ???',
    'avec',
    '    liste λ ; élément e, e′');
  var DERNIER = spec(
    'opérations',
    '    dernier : liste → élément',
    'préconditions',
    '    dernier(λ) est-défini-ssi λ ≠ listevide',
    'axiomes',
    '    dernier(cons(e, listevide)) = e',
    '    λ ≠ listevide ⇒ dernier(cons(e, λ)) = dernier(λ)',
    'avec',
    '    liste λ ; élément e');
  var MYST_REC = spec(
    'opérations',
    '    mystère : liste × élément → liste',
    'axiomes',
    '    mystère(listevide, x) = listevide',
    '    e = x ⇒ mystère(cons(e, λ), x) = mystère(λ, x)',
    '    e ≠ x ⇒ mystère(cons(e, λ), x) = cons(e, mystère(λ, x))',
    'avec',
    '    liste λ ; élément e, x');
  var MYST_INV = spec(
    'opérations',
    '    mystère : liste → liste',
    'axiomes',
    '    longueur(mystère(λ)) = longueur(λ)',
    '    1 ≤ i ≤ longueur(λ)',
    '        ⇒ ième(mystère(λ), i) = ième(λ, longueur(λ) − i + 1)',
    'avec',
    '    liste λ ; entier i');
  var MYST_ROT = spec(
    'opérations',
    '    mystère : liste → liste',
    'préconditions',
    '    mystère(λ) est-défini-ssi λ ≠ listevide',
    'axiomes',
    '    longueur(mystère(λ)) = longueur(λ)',
    '    1 ≤ i < longueur(λ) ⇒ ième(mystère(λ), i) = ième(λ, i + 1)',
    '    ième(mystère(λ), longueur(λ)) = ième(λ, 1)',
    'avec',
    '    liste λ ; entier i');
  var MYST_ECH = spec(
    'opérations',
    '    mystère : liste × entier × entier → liste',
    'préconditions',
    '    mystère(λ, x, y) est-défini-ssi 1 ≤ x ≤ longueur(λ) & 1 ≤ y ≤ longueur(λ)',
    'axiomes',
    '    longueur(mystère(λ, x, y)) = longueur(λ)',
    '    i = x ⇒ ième(mystère(λ, x, y), i) = ième(λ, y)',
    '    i = y ⇒ ième(mystère(λ, x, y), i) = ième(λ, x)',
    '    1 ≤ i ≤ longueur(λ) & i ≠ x & i ≠ y',
    '        ⇒ ième(mystère(λ, x, y), i) = ième(λ, i)',
    'avec',
    '    liste λ ; entier i, x, y');
  /* opération mystère de l’examen d’octobre 2024 (promo 2029) */
  var MYST_SUP = spec(
    'opérations',
    '    mystère : liste × entier × entier → liste',
    'préconditions',
    '    mystère(λ, x, y) est-défini-ssi 1 ≤ x ≤ y ≤ longueur(λ)',
    'axiomes',
    '    longueur(mystère(λ, x, y)) = longueur(λ) − y + x − 1',
    '    1 ≤ i < x ⇒ ième(mystère(λ, x, y), i) = ième(λ, i)',
    '    x ≤ i ≤ longueur(λ) − y + x − 1',
    '        ⇒ ième(mystère(λ, x, y), i) = ième(λ, i + y − x + 1)',
    'avec',
    '    liste λ ; entier i, x, y');
  var MYST_FIN = spec(
    'opérations',
    '    mystère : liste × élément → liste',
    'axiomes',
    '    longueur(mystère(λ, e)) = longueur(λ) + 1',
    '    1 ≤ i ≤ longueur(λ) ⇒ ième(mystère(λ, e), i) = ième(λ, i)',
    '    i = longueur(λ) + 1 ⇒ ième(mystère(λ, e), i) = e',
    'avec',
    '    liste λ ; entier i ; élément e');
  var INS_FAUX = spec(
    'axiomes',
    '    longueur(insérer(λ, k, e)) = longueur(λ) + 1',
    '    1 ≤ i ≤ k ⇒ ième(insérer(λ, k, e), i) = ième(λ, i)',
    '    k = i ⇒ ième(insérer(λ, k, e), i) = e',
    '    k < i ≤ longueur(λ) + 1 ⇒ ième(insérer(λ, k, e), i) = ième(λ, i − 1)');

  var Q = [
    /* ================= chapitre 1 : types abstraits ================= */
    /* ---------- signature et vocabulaire ---------- */
    { id: 'taa-c1-01', topic: 'taa-signature', lvl: 1, type: 'single', q: 'La définition d’un type algébrique abstrait est composée…',
      o: ['d’une signature et d’un système d’axiomes', 'd’une signature seulement : les axiomes sont facultatifs', 'd’une liste de types et de leur programmation', 'd’axiomes seulement : les opérations s’en déduisent'], a: 0,
      x: 'C’est la phrase d’ouverture du cours : une signature (les types et les opérations) et un système d’axiomes qui la caractérise. La signature ne donne que des noms et des profils : sans axiomes, rien ne dit ce que font les opérations. Et les axiomes ont besoin de la signature pour savoir de quelles opérations ils parlent.', ref: C1 + '#s1' },
    { id: 'taa-c1-02', topic: 'taa-signature', lvl: 1, type: 'multi', q: 'Quelles parties d’une spécification ne font <em>pas</em> partie de la signature ?',
      o: ['<code>préconditions</code>', '<code>axiomes</code>', '<code>avec</code>', '<code>types</code>', '<code>opérations</code>'], a: [0, 1, 2],
      x: 'La signature, ce sont les types et les opérations avec leur profil. Les préconditions et les axiomes donnent les propriétés des opérations ; la partie <code>avec</code> donne le type des noms utilisés dans ces formules.', ref: C1 + '#s2' },
    { id: 'taa-c1-03', topic: 'taa-signature', lvl: 1, type: 'single', q: 'Dans la signature, une opération se déclare par…',
      o: ['son identifiant (son nom) et son profil', 'son nom et ses axiomes', 'son profil et sa précondition', 'son nom seulement : le reste se lit dans les axiomes'], a: 0,
      x: 'Pour chaque opération, on donne son identifiant et son profil : les types de ses arguments et le type de son résultat, par exemple <code>longueur : liste → entier</code>. Les préconditions et les axiomes viennent plus loin, dans leurs propres parties.', ref: C1 + '#s2' },
    { id: 'taa-c1-04', topic: 'taa-signature', lvl: 1, type: 'single', q: 'Que dit le profil <code>ième : liste × entier → élément</code> ?',
      o: ['ième prend une liste et un entier, et renvoie un élément', 'ième prend une liste, et renvoie un entier et un élément', 'ième prend un élément, et renvoie une liste et un entier', 'ième prend une liste, un entier et un élément'], a: 0,
      x: 'À gauche de la flèche, les types des arguments, séparés par × ; à droite, le type du résultat. On l’utilise sous la forme <code>ième(λ, i)</code>. L’élément est ce que l’opération renvoie, ce n’est pas un argument.', ref: C1 + '#s2' },
    { id: 'taa-c1-05', topic: 'taa-signature', lvl: 1, type: 'single', q: 'Avec le profil <code>supprimer : liste × entier → liste</code>, quelle écriture est correcte ?',
      o: ['<code>supprimer(λ, 2)</code>', '<code>supprimer(2, λ)</code>', '<code>supprimer(λ)</code>', '<code>supprimer(λ, 2, e)</code>'], a: 0,
      x: 'Les arguments se placent dans l’ordre du profil : d’abord la liste, puis l’entier, et il en faut exactement deux. Attention : dans le type ensemble, <code>supprimer : élément × ensemble → ensemble</code> prend ses arguments dans l’autre ordre, <code>supprimer(x, e)</code>. C’est toujours le profil qui décide.', ref: C1 + '#s2' },
    { id: 'taa-c1-06', topic: 'taa-signature', lvl: 1, type: 'num', a: 3, q: 'Combien d’arguments prend l’opération <code>insérer : liste × entier × élément → liste</code> ?',
      x: 'Trois types à gauche de la flèche : une liste, un entier (le rang) et un élément. Le type à droite de la flèche est celui du résultat, ce n’est pas un argument. On écrit <code>insérer(λ, k, e)</code>.', ref: C1 + '#s2' },
    { id: 'taa-c1-07', topic: 'taa-signature', lvl: 1, type: 'single', q: 'Le profil <code>Faux : → booléen</code> n’a rien à gauche de la flèche. <code>Faux</code> est…',
      o: ['une constante : une opération sans argument', 'une opération mal déclarée : il lui manque un argument', 'une opération partielle', 'un observateur'], a: 0,
      x: 'Rien avant la flèche : aucun argument. C’est une constante, que l’on écrit sans parenthèses : <code>Faux</code>. <code>listevide : → liste</code> et <code>pilevide : → pile</code> sont aussi des constantes. Ce n’est pas un observateur : un observateur a au moins un argument de type défini.', ref: C1 + '#s2' },
    { id: 'taa-c1-08', topic: 'taa-signature', lvl: 2, type: 'multi', q: 'Parmi ces opérations, lesquelles sont des constantes ?',
      o: ['<code>listevide : → liste</code>', '<code>Faux : → booléen</code>', '<code>estvide : pile → booléen</code>', '<code>fin : liste → liste</code>', '<code>card : ensemble → entier</code>'], a: [0, 1],
      x: 'Une constante n’a aucun argument : rien à gauche de la flèche. Le type du résultat n’entre pas en compte : <code>listevide</code> renvoie une liste, <code>Faux</code> un booléen. <code>estvide</code>, <code>fin</code> et <code>card</code> prennent chacune un argument.', ref: C1 + '#s2' },
    { id: 'taa-c1-09', topic: 'taa-signature', lvl: 1, type: 'single', q: 'Que signifient les tirets bas dans <code>_^_ : entier × entier → entier</code> ?',
      o: ['l’opération s’écrit entre ses deux arguments : <code>4^2</code>', 'l’opération n’a pas d’argument', 'les arguments sont facultatifs', 'l’opération est partielle'], a: 0,
      x: 'Chaque <code>_</code> marque la place d’un argument : <code>_^_</code> s’utilise en notation infixe, <code>4^2</code>. C’est la même chose pour <code>_∈_ : élément × ensemble → booléen</code>, qu’on écrit <code>x ∈ e</code>. Le profil compte bien deux arguments.', ref: C1 + '#s2' },
    { id: 'taa-c1-10', topic: 'taa-signature', lvl: 2, type: 'single', q: 'Tu veux une opération <code>concaténer</code> qui prend deux listes et renvoie la liste formée de la première suivie de la seconde. Quel est son profil ?',
      o: ['<code>concaténer : liste × liste → liste</code>', '<code>concaténer : liste → liste × liste</code>', '<code>concaténer : liste × liste → liste × liste</code>', '<code>concaténer : liste → liste</code>'], a: 0,
      x: 'Les deux listes données sont les arguments : elles vont à gauche de la flèche, séparées par ×. Le résultat est une seule liste, à droite. Une opération qui ne prend qu’une liste ne peut pas en recevoir deux.', ref: C1 + '#s2' },
    { id: 'taa-c1-11', topic: 'taa-signature', lvl: 2, type: 'single', q: 'Dans quelle partie de la spécification écris-tu <code>liste λ</code> et <code>entier i, k</code> ?',
      o: ['<code>avec</code>', '<code>types</code>', '<code>utilise</code>', '<code>opérations</code>'], a: 0,
      x: 'On termine par la partie <code>avec</code>, qui donne le type de chaque nom utilisé dans les préconditions et les axiomes. <code>types</code> et <code>utilise</code> contiennent des noms de types (liste, entier), pas des noms de variables comme λ ou i.', ref: C1 + '#s6' },
    { id: 'taa-c1-12', topic: 'taa-signature', lvl: 1, type: 'tf', a: true, q: 'Dans la partie <code>types</code>, on écrit les noms des types que l’on est en train de définir.',
      x: 'Vrai. Par exemple <code>types pile</code>, ou <code>types liste, place</code> pour les listes. Les types déjà conçus dont on se sert (entier, booléen, élément) vont dans <code>utilise</code>.', ref: C1 + '#s2' },
    { id: 'taa-c1-13', topic: 'taa-signature', lvl: 2, type: 'single', q: 'Avec <code>supprimer : liste × entier → liste</code> et <code>longueur : liste → entier</code>, de quel type est le terme <code>longueur(supprimer(λ, 2))</code> ?',
      o: ['entier', 'liste', 'élément', 'liste × entier'], a: 0,
      x: 'On lit de l’intérieur vers l’extérieur : <code>supprimer(λ, 2)</code> est une liste, et <code>longueur</code> appliquée à une liste renvoie un entier. Le type d’un terme est celui du résultat de l’opération la plus extérieure.', ref: C1 + '#s2' },

    /* ---------- hiérarchie : types et opérations ---------- */
    { id: 'taa-c1-14', topic: 'taa-hierarchie', lvl: 1, type: 'single', q: 'Dans une spécification, un type <em>prédéfini</em> est…',
      o: ['un type qui existe déjà (« déjà conçu »), cité dans <code>utilise</code>', 'un type nouveau, en conception, cité dans <code>types</code>', 'un type qui n’a aucune opération', 'un type cité dans <code>avec</code>'], a: 0,
      x: 'Défini : nouveau, en conception, écrit dans <code>types</code>. Prédéfini : existe déjà, déjà conçu, écrit dans <code>utilise</code>, avant les opérations. Dans la pile, <code>pile</code> est défini ; <code>booléen</code> et <code>élément</code> sont prédéfinis. La partie <code>avec</code> déclare des variables, pas des types.', ref: C1 + '#s3' },
    { id: 'taa-c1-15', topic: 'taa-hierarchie', lvl: 1, type: 'single', q: 'Une opération interne est une opération…',
      o: ['qui renvoie un résultat de type défini', 'dont tous les arguments sont de type défini', 'qui renvoie un résultat de type prédéfini', 'qui n’a pas de précondition'], a: 0,
      x: 'Seul le type du résultat compte : une opération interne renvoie une valeur du type que l’on définit (elle modifie l’état de la donnée elle-même). Ses arguments peuvent être de n’importe quel type : <code>empiler : pile × élément → pile</code> prend un élément. Un résultat de type prédéfini, c’est le cas des observateurs. Et être partielle ou non n’a rien à voir.', ref: C1 + '#s4' },
    { id: 'taa-c1-16', topic: 'taa-hierarchie', lvl: 1, type: 'single', q: 'Un observateur est une opération qui…',
      o: ['a au moins un argument de type défini et renvoie un résultat de type prédéfini', 'renvoie un résultat de type défini', 'n’a aucun argument', 'n’a que des arguments de type prédéfini'], a: 0,
      x: 'Il faut les deux conditions : au moins un argument du type que l’on définit (on observe cette donnée) et un résultat de type prédéfini (ce que l’on apprend sur elle). <code>longueur : liste → entier</code> en est un. Une opération sans argument est une constante ; un résultat de type défini, c’est une opération interne.', ref: C1 + '#s4' },
    { id: 'taa-c1-17', topic: 'taa-hierarchie', lvl: 1, type: 'single', q: 'Dans le type pile (<code>types pile</code>, <code>utilise booléen, élément</code>), l’opération <code>sommet : pile → élément</code> est…',
      o: ['un observateur', 'une opération interne', 'une constante', 'ni interne ni observateur, car elle est partielle'], a: 0,
      x: 'Son argument est une pile (type défini) et son résultat un élément (type prédéfini, dans <code>utilise</code>) : c’est un observateur. Qu’elle soit partielle (pas de sommet pour une pile vide) ne change pas sa nature : partielle et observateur sont deux questions différentes.', ref: C1 + '#s4' },
    { id: 'taa-c1-18', topic: 'taa-hierarchie', lvl: 2, type: 'multi', q: 'Dans le type pile (<code>types pile</code>, <code>utilise booléen, élément</code>), lesquelles sont des opérations internes ?',
      o: ['<code>pilevide : → pile</code>', '<code>empiler : pile × élément → pile</code>', '<code>dépiler : pile → pile</code>', '<code>sommet : pile → élément</code>', '<code>estvide : pile → booléen</code>'], a: [0, 1, 2],
      x: 'Les opérations internes renvoient une pile : <code>pilevide</code> (une constante), <code>empiler</code> et <code>dépiler</code>. <code>sommet</code> renvoie un élément et <code>estvide</code> un booléen, deux types prédéfinis : ce sont les observateurs de la pile.', ref: C1 + '#s4' },
    { id: 'taa-c1-19', topic: 'taa-hierarchie', lvl: 2, type: 'multi', q: 'Dans la liste itérative (<code>types liste, place</code>, <code>utilise entier, élément</code>), lesquelles sont des observateurs ?',
      o: ['<code>ième : liste × entier → élément</code>', '<code>longueur : liste → entier</code>', '<code>insérer : liste × entier × élément → liste</code>', '<code>supprimer : liste × entier → liste</code>', '<code>listevide : → liste</code>'], a: [0, 1],
      x: '<code>ième</code> et <code>longueur</code> prennent une liste et renvoient un type prédéfini (élément, entier) : ce sont des observateurs. <code>insérer</code>, <code>supprimer</code> et la constante <code>listevide</code> renvoient une liste : ce sont des opérations internes, même si <code>insérer</code> et <code>supprimer</code> ont aussi un argument entier.', ref: C1 + '#s4' },
    { id: 'taa-c1-20', topic: 'taa-hierarchie', lvl: 2, type: 'single', q: 'Dans le type vecteur (<code>types vecteur</code>, <code>utilise entier, booléen, élément</code>), <code>vect : entier × entier → vecteur</code> n’a aucun argument de type vecteur. C’est…',
      o: ['une opération interne', 'un observateur', 'une constante', 'une opération qui ne peut pas appartenir à ce type'], a: 0,
      x: 'Pour être interne, il suffit de renvoyer un résultat de type défini : <code>vect</code> renvoie un vecteur. Les types des arguments ne comptent pas. Ce n’est pas une constante, puisqu’elle a deux arguments (les bornes du vecteur). Ce n’est pas un observateur : son résultat n’est pas prédéfini.', ref: C1 + '#s4' },
    { id: 'taa-c1-21', topic: 'taa-hierarchie', lvl: 2, type: 'multi', q: 'Dans le type vecteur (<code>types vecteur</code>, <code>utilise entier, booléen, élément</code>), lesquelles sont des observateurs ?',
      o: ['<code>ième : vecteur × entier → élément</code>', '<code>estinitialisé : vecteur × entier → booléen</code>', '<code>borneinf : vecteur → entier</code>', '<code>modifième : vecteur × entier × élément → vecteur</code>'], a: [0, 1, 2],
      x: 'Les trois premières prennent un vecteur et renvoient un type prédéfini (élément, booléen, entier) : ce sont des observateurs. <code>modifième</code> renvoie un vecteur : c’est une opération interne, comme <code>vect</code>.', ref: C1 + '#s4' },
    { id: 'taa-c1-22', topic: 'taa-hierarchie', lvl: 2, type: 'single', q: 'Dans l’exercice du type Booléen, la spécification commence par <code>types booléen</code>. L’opération <code>non : booléen → booléen</code> y est…',
      o: ['une opération interne', 'un observateur', 'une constante', 'une opération partielle'], a: 0,
      x: 'Ici, <code>booléen</code> est le type que l’on définit : il est dans <code>types</code>. <code>non</code> renvoie un booléen, donc une valeur du type défini : c’est une opération interne. Dans la pile, au contraire, booléen est prédéfini et <code>estvide : pile → booléen</code> est un observateur. Enfin <code>non</code> est définie pour vrai comme pour faux : elle n’est pas partielle.', ref: C1 + '#s8' },
    { id: 'taa-c1-23', topic: 'taa-hierarchie', lvl: 2, type: 'tf', a: true, q: 'Un même type peut être défini dans une spécification et prédéfini dans une autre.',
      x: 'Vrai. Tout dépend de la spécification que l’on écrit. <code>booléen</code> est défini dans l’exercice du type Booléen (il est dans <code>types</code>) et prédéfini dans le type pile (il est dans <code>utilise</code>).', ref: C1 + '#s3' },
    { id: 'taa-c1-24', topic: 'taa-hierarchie', lvl: 2, type: 'num', a: 2, q: 'Combien d’observateurs compte cette signature ?', fig: COMPTEUR,
      x: 'Les observateurs prennent un compteur et renvoient un type prédéfini : <code>valeur</code> (→ entier) et <code>estnul</code> (→ booléen). <code>nouveau</code>, <code>incr</code> et <code>raz</code> renvoient un compteur : ce sont des opérations internes, et <code>nouveau</code> est en plus une constante.', ref: C1 + '#s4' },
    { id: 'taa-c1-25', topic: 'taa-hierarchie', lvl: 2, type: 'single', q: 'Dans la spécification de la liste itérative, où est déclaré le type <code>entier</code> ?',
      o: ['dans <code>utilise</code> : c’est un type prédéfini', 'dans <code>types</code> : c’est un type défini', 'dans <code>avec</code>', 'nulle part : il est connu de tous'], a: 0,
      x: 'La liste itérative se sert des entiers pour les rangs, mais ne les définit pas : <code>entier</code> est déjà conçu, on le cite dans <code>utilise</code>. La partie <code>avec</code> déclare des variables de type entier (<code>entier i, k</code>), pas le type lui-même. Tout type prédéfini dont on se sert doit apparaître dans <code>utilise</code>.', ref: C1 + '#s3' },
    { id: 'taa-c1-26', topic: 'taa-hierarchie', lvl: 2, type: 'single', q: 'On ajoute à la liste récursive (<code>utilise élément</code>) l’opération <code>est-présent : élément × liste → booléen</code>. Que faut-il aussi changer dans la spécification ?',
      o: ['ajouter <code>booléen</code> dans <code>utilise</code>', 'ajouter <code>booléen</code> dans <code>types</code>', 'rien : booléen est connu de tous', 'ajouter <code>booléen b</code> dans <code>avec</code>'], a: 0,
      x: 'Le profil se sert du type booléen, qui existe déjà : c’est un type prédéfini, à citer dans <code>utilise</code>, qui ne contenait que <code>élément</code>. On ne le met pas dans <code>types</code>, car on ne le définit pas. La partie <code>avec</code> ne sert qu’à typer les variables des axiomes.', ref: C1 + '#s3' },
    { id: 'taa-c1-27', topic: 'taa-hierarchie', lvl: 2, type: 'single', q: 'Dans la liste récursive, l’opération <code>est-présent : élément × liste → booléen</code> est…',
      o: ['un observateur : un argument de type liste et un résultat booléen', 'une opération interne : elle a un argument de type liste', 'une constante', 'ni l’un ni l’autre : son premier argument est un élément'], a: 0,
      x: 'Il suffit d’un argument de type défini (la liste) et d’un résultat de type prédéfini (booléen) : c’est un observateur. L’ordre des arguments ne compte pas. Ce n’est pas une opération interne : elle ne renvoie pas une liste.', ref: C1 + '#s4' },

    /* ---------- préconditions ---------- */
    { id: 'taa-c1-28', topic: 'taa-precond', lvl: 1, type: 'single', q: 'Comment appelle-t-on une opération qui n’est pas définie partout ?',
      o: ['une opération partielle', 'un observateur', 'une constante', 'une opération interne'], a: 0,
      x: 'Une opération partielle n’a de sens que pour une partie de ses arguments ; son domaine de définition est donné dans les préconditions. Partielle ne dit rien sur interne ou observateur : <code>dépiler</code> (interne) et <code>sommet</code> (observateur) sont toutes deux partielles.', ref: C1 + '#s5' },
    { id: 'taa-c1-29', topic: 'taa-precond', lvl: 1, type: 'single', q: 'Que signifie <code>dépiler(p) est-défini-ssi estvide(p) = faux</code> ?',
      o: ['<code>dépiler(p)</code> a un sens si et seulement si la pile p n’est pas vide', '<code>dépiler(p)</code> renvoie faux quand p est vide', '<code>dépiler(p)</code> renvoie toujours une pile vide', '<code>dépiler(p)</code> vide la pile p si elle ne l’était pas'], a: 0,
      x: '« ssi » se lit « si et seulement si ». La précondition donne le domaine de définition : on ne dépile pas une pile vide. Elle ne dit rien du résultat, c’est le rôle des axiomes ; et <code>dépiler</code> renvoie une pile, jamais un booléen.', ref: C1 + '#s5' },
    { id: 'taa-c1-30', topic: 'taa-precond', lvl: 1, type: 'tf', a: false, q: 'Il faut écrire une précondition pour chaque opération de la signature.',
      x: 'Faux. Les préconditions ne concernent que les opérations partielles. <code>empiler</code>, <code>cons</code> ou <code>longueur</code> sont définies partout : elles n’ont pas de précondition.', ref: C1 + '#s5' },
    { id: 'taa-c1-31', topic: 'taa-precond', lvl: 1, type: 'single', q: 'Où écrit-on le domaine de définition d’une opération partielle ?',
      o: ['dans la partie <code>préconditions</code>, avant les axiomes', 'dans la partie <code>opérations</code>, à côté du profil', 'dans la partie <code>avec</code>', 'dans la partie <code>utilise</code>'], a: 0,
      x: 'Il faut d’abord donner les préconditions, c’est-à-dire les domaines de définition des opérations partielles, sous la forme <code>… est-défini-ssi …</code>. Les axiomes viennent ensuite. Le profil ne dit que les types, pas les valeurs permises.', ref: C1 + '#s5' },
    { id: 'taa-c1-32', topic: 'taa-precond', lvl: 3, type: 'single', q: 'Dans le type vecteur, <code>ième(v, i) est-défini-ssi borneinf(v) ≤ i ≤ bornesup(v) &amp; estinitialisé(v, i) = vrai</code>. Le terme <code>ième(modifième(vect(1, 5), 2, a), 3)</code> est-il défini ?',
      o: ['non : la case 3 n’a jamais reçu de valeur', 'oui : 3 est entre les bornes 1 et 5', 'oui, et il vaut a', 'non : 3 est en dehors des bornes'], a: 0,
      x: '3 est bien entre borneinf = 1 et bornesup = 5, mais il faut aussi que la case 3 soit initialisée. Or <code>modifième</code> n’a rempli que la case 2 : <code>estinitialisé(modifième(vect(1, 5), 2, a), 3) = estinitialisé(vect(1, 5), 3) = faux</code>. Les deux conditions de la précondition doivent être vraies.', ref: C1 + '#s8' },

    /* ---------- axiomes ---------- */
    { id: 'taa-c1-33', topic: 'taa-axiomes', lvl: 1, type: 'single', q: 'Comment écrit-on les axiomes qui définissent les opérations internes ?',
      o: ['en appliquant les observateurs aux opérations internes', 'en appliquant les opérations internes aux observateurs', 'en donnant un exemple de valeur pour chaque opération', 'en recopiant les préconditions avec le signe ='], a: 0,
      x: 'Pour savoir ce que fait une opération interne, on lui applique ses observateurs : <code>sommet(empiler(p, e)) = e</code> applique l’observateur <code>sommet</code> à l’opération interne <code>empiler</code>. L’observateur est à l’extérieur, l’opération interne à l’intérieur. Un exemple ne vaut que pour une valeur ; un axiome vaut pour toutes.', ref: C1 + '#s6' },
    { id: 'taa-c1-34', topic: 'taa-axiomes', lvl: 1, type: 'multi', q: 'Quelles propriétés l’ensemble des axiomes doit-il respecter ?',
      o: ['la consistance', 'la complétude', 'la récursivité', 'la commutativité'], a: [0, 1],
      x: 'Consistance : pas d’axiomes contradictoires. Complétude : avoir écrit suffisamment d’axiomes. Ce sont les deux problèmes à surveiller quand on conçoit les axiomes.', ref: C1 + '#s8' },
    { id: 'taa-c1-35', topic: 'taa-axiomes', lvl: 1, type: 'single', q: 'Un ensemble d’axiomes est <em>consistant</em> quand…',
      o: ['aucun axiome n’en contredit un autre', 'il y a suffisamment d’axiomes', 'chaque opération a une précondition', 'chaque axiome contient une implication ⇒'], a: 0,
      x: 'La consistance, c’est l’absence d’axiomes contradictoires : on ne doit jamais pouvoir calculer deux valeurs différentes pour un même terme. « Suffisamment d’axiomes », c’est la complétude, l’autre propriété.', ref: C1 + '#s8' },
    { id: 'taa-c1-36', topic: 'taa-axiomes', lvl: 2, type: 'single', q: 'Dans le type pile, on oublie l’axiome <code>estvide(pilevide) = vrai</code>. Quel est le problème ?',
      o: ['un défaut de complétude : plus rien ne donne la valeur de <code>estvide(pilevide)</code>', 'un défaut de consistance : deux axiomes se contredisent', 'aucun : cette valeur va de soi', 'un défaut de précondition : <code>estvide</code> devient partielle'], a: 0,
      x: 'Il manque un axiome : on ne peut plus calculer l’observateur <code>estvide</code> sur l’opération interne <code>pilevide</code>. C’est un défaut de complétude. La consistance concerne des axiomes qui se contredisent, pas des axiomes absents. Et rien ne « va de soi » : seuls les axiomes disent ce que valent les opérations.', ref: C1 + '#s8' },
    { id: 'taa-c1-37', topic: 'taa-axiomes', lvl: 2, type: 'single', q: 'Dans le type file, on remplace <code>estvide(f) = vrai ⇒ premier(enfiler(f, e)) = e</code> par <code>premier(enfiler(f, e)) = e</code>, sans condition, et on garde <code>estvide(f) = faux ⇒ premier(enfiler(f, e)) = premier(f)</code>. Quel problème apparaît ?',
      o: ['un défaut de consistance : pour une file f non vide, les deux axiomes peuvent donner deux valeurs différentes', 'un défaut de complétude : le cas de la file vide n’est plus couvert', 'aucun : les deux axiomes disent la même chose', 'un défaut de précondition : <code>premier</code> devient définie partout'], a: 0,
      x: 'Prends f = <code>enfiler(filevide, a)</code> et e = b : l’axiome sans condition donne b, l’autre donne <code>premier(f)</code>, c’est-à-dire a. Deux valeurs pour un même terme : défaut de consistance. Le cas de la file vide reste couvert, par l’axiome sans condition. C’est pour cela que le cours écrit <code>estvide(f) = vrai ⇒</code> devant le premier.', ref: C1 + '#s8' },
    { id: 'taa-c1-38', topic: 'taa-axiomes', lvl: 3, type: 'single', q: 'Dans une version erronée du type vecteur, on trouve ces deux axiomes. Que leur reproches-tu ?', fig: VECT_IJ,
      o: ['ils se contredisent quand j = i : il manque <code>i ≠ j</code> dans le second (consistance)', 'le cas j = i n’est couvert par aucun axiome (complétude)', 'rien : ils sont corrects', 'le second devrait être une précondition'], a: 0,
      x: 'Pour j = i, le second axiome donne <code>estinitialisé(modifième(v, i, e), i) = estinitialisé(v, i)</code>, qui peut valoir faux, alors que le premier dit vrai. Deux axiomes contradictoires : c’est un défaut de consistance. La correction ajoute <code>&amp; i ≠ j</code> au second. Le cas j = i n’est pas oublié, il est au contraire traité deux fois.', ref: C1 + '#s8' },
    { id: 'taa-c1-39', topic: 'taa-axiomes', lvl: 2, type: 'single', q: 'Dans le type vecteur, on retire l’axiome <code>estinitialisé(vect(i, j), k) = faux</code>. Quel terme ne peut-on plus calculer ?',
      o: ['<code>estinitialisé(vect(1, 5), 3)</code>', '<code>borneinf(vect(1, 5))</code>', '<code>ième(modifième(vect(1, 5), 3, a), 3)</code>', 'aucun : les autres axiomes suffisent'], a: 0,
      x: 'Sans cet axiome, l’observateur <code>estinitialisé</code> n’est plus appliqué à l’opération interne <code>vect</code> : rien ne dit si une case d’un vecteur neuf est initialisée. C’est un défaut de complétude. <code>borneinf(vect(1, 5)) = 1</code> et <code>ième(modifième(vect(1, 5), 3, a), 3) = a</code> se calculent toujours avec leurs propres axiomes.', ref: C1 + '#s8' },
    { id: 'taa-c1-40', topic: 'taa-axiomes', lvl: 2, type: 'single', q: 'Que dit l’axiome <code>longueur(insérer(λ, k, e)) = longueur(λ) + 1</code> ?',
      o: ['qu’une insertion ajoute exactement un élément', 'que e est placé en dernière position', 'que <code>insérer</code> est définie pour tout k', 'que la liste obtenue contient k + 1 éléments'], a: 0,
      x: 'L’observateur <code>longueur</code>, appliqué à l’opération interne <code>insérer</code>, dit que la liste obtenue a un élément de plus que λ. La place de e est donnée par les axiomes de <code>ième</code>, le domaine de k par la précondition. Le rang k ne dit rien de la longueur.', ref: C1 + '#s6' },
    { id: 'taa-c1-41', topic: 'taa-axiomes', lvl: 2, type: 'single', q: 'Avec les axiomes <code>non(vrai) = faux</code> et <code>non(faux) = vrai</code>, que vaut <code>non(non(faux))</code> ?',
      o: ['faux', 'vrai', 'non défini', '<code>non(faux)</code>'], a: 0,
      x: 'On réécrit de l’intérieur vers l’extérieur : <code>non(faux) = vrai</code>, puis <code>non(vrai) = faux</code>. <code>non(faux)</code> n’est pas une réponse terminée : il se réécrit en vrai, qui n’est pas la valeur du terme.', ref: C1 + '#s7' },
    { id: 'taa-c1-42', topic: 'taa-axiomes', lvl: 2, type: 'single', q: 'Pour <code>non : booléen → booléen</code>, on n’écrit qu’un axiome : <code>non(vrai) = faux</code>. Que manque-t-il ?',
      o: ['un axiome pour <code>non(faux)</code> : la spécification n’est pas complète', 'rien : <code>non(faux) = vrai</code> se déduit du premier axiome', 'une précondition sur <code>non</code>', 'rien, mais cet axiome rend la spécification inconsistante'], a: 0,
      x: 'Aucun axiome ne permet de calculer <code>non(faux)</code> : il faut écrire <code>non(faux) = vrai</code>. C’est un défaut de complétude. Rien ne se « déduit » sans axiome. Un seul axiome ne peut pas en contredire un autre, et <code>non</code> est définie partout : pas de précondition.', ref: C1 + '#s8' },
    { id: 'taa-c1-43', topic: 'taa-axiomes', lvl: 2, type: 'single', q: 'Dans l’axiome <code>1 ≤ i &lt; k ⇒ ième(supprimer(λ, k), i) = ième(λ, i)</code>, que représente la partie à gauche de ⇒ ?',
      o: ['la condition sous laquelle l’égalité est vraie', 'la précondition de <code>supprimer</code>', 'le résultat de <code>ième</code>', 'le type des variables i et k'], a: 0,
      x: 'Un axiome peut être conditionnel : l’égalité ne vaut que si la condition à gauche de ⇒ est vraie. Ici, elle ne concerne que les rangs i situés avant k. Ce n’est pas la précondition de <code>supprimer</code>, qui est dans la partie <code>préconditions</code> : la condition porte sur i, le rang qu’on observe. Les types sont dans <code>avec</code>.', ref: C1 + '#s7' },
    { id: 'taa-c1-44', topic: 'taa-axiomes', lvl: 2, type: 'single', q: 'Les axiomes de la pile ne disent rien de <code>sommet(pilevide)</code>. Est-ce un défaut de complétude ?',
      o: ['non : la précondition de <code>sommet</code> exclut ce terme', 'oui : il faut ajouter <code>sommet(pilevide) = faux</code>', 'oui : il faut ajouter <code>sommet(pilevide) = pilevide</code>', 'non : <code>sommet(pilevide)</code> vaut vrai par défaut'], a: 0,
      x: '<code>sommet(p) est-défini-ssi estvide(p) = faux</code> : <code>sommet(pilevide)</code> n’existe pas, aucun axiome n’a à le décrire. Les deux axiomes proposés seraient d’ailleurs faux : <code>sommet</code> renvoie un élément, ni un booléen ni une pile.', ref: C1 + '#s8' },

    /* ================= chapitre 2 : listes ================= */
    /* ---------- listes récursives ---------- */
    { id: 'taa-c2-01', topic: 'taa-liste-rec', lvl: 1, type: 'single', q: 'Comment s’écrit la liste λ = {e1, e2, e3} avec les opérations de la liste récursive ?',
      o: ['<code>cons(e1, cons(e2, cons(e3, listevide)))</code>', '<code>cons(e3, cons(e2, cons(e1, listevide)))</code>', '<code>cons(cons(cons(listevide, e1), e2), e3)</code>', '<code>cons(e1, e2, e3)</code>'], a: 0,
      x: '<code>cons(e, λ)</code> ajoute e en tête de λ. Le terme se lit dans l’ordre de la liste : e1 en tête, puis e2, puis e3, et <code>listevide</code> au bout. Les deux dernières écritures ne respectent pas le profil <code>cons : élément × liste → liste</code> (un élément, puis une liste).', ref: C2 + '#s3' },
    { id: 'taa-c2-02', topic: 'taa-liste-rec', lvl: 1, type: 'single', q: 'Que vaut <code>fin(cons(a, cons(b, cons(c, listevide))))</code> ?',
      o: ['<code>cons(b, cons(c, listevide))</code>', 'a', '<code>cons(a, cons(b, listevide))</code>', '<code>cons(c, listevide)</code>'], a: 0,
      x: '<code>fin(cons(e, λ)) = λ</code> : on retire l’élément de tête et on garde le reste de la liste. Le résultat est une liste, pas un élément (c’est <code>premier</code> qui renverrait a). Et c’est la tête qu’on enlève, pas le dernier élément.', ref: C2 + '#s2' },
    { id: 'taa-c2-03', topic: 'taa-liste-rec', lvl: 1, type: 'single', q: 'Dans une liste récursive, quel élément est immédiatement accessible ?',
      o: ['seulement l’élément de tête', 'tous les éléments, par leur rang', 'seulement le dernier élément', 'le premier et le dernier'], a: 0,
      x: 'Seul l’élément de tête est immédiatement accessible, avec <code>premier</code>. Pour lire le troisième, on passe deux fois par <code>fin</code> : <code>premier(fin(fin(λ)))</code>. L’accès direct par le rang, c’est la liste itérative.', ref: C2 + '#s2' },
    { id: 'taa-c2-04', topic: 'taa-liste-rec', lvl: 2, type: 'num', a: 3, q: 'λ = <code>cons(a, cons(b, cons(c, cons(d, listevide))))</code>. Combien de fois faut-il appliquer <code>fin</code> à λ pour que <code>premier</code> du résultat donne d ?',
      x: 'd est le 4e élément : il faut retirer les trois qui le précèdent, <code>premier(fin(fin(fin(λ)))) = d</code>. Avec quatre <code>fin</code>, on obtiendrait <code>listevide</code>, et <code>premier(listevide)</code> n’est pas défini.', ref: C2 + '#s3' },
    { id: 'taa-c2-05', topic: 'taa-liste-rec', lvl: 3, type: 'single', q: 'Que vaut <code>contenu(succ(tête(cons(a, cons(b, cons(c, listevide))))))</code> ?',
      o: ['b', 'a', 'c', 'non défini : <code>succ</code> ne s’applique pas à une tête'], a: 0,
      x: 'Note λ = <code>cons(a, cons(b, cons(c, listevide)))</code>. L’axiome <code>succ(tête(λ)) = tête(fin(λ))</code> dit que la place qui suit la tête est la tête de la fin. Puis <code>premier(λ) = contenu(tête(λ))</code> donne <code>contenu(tête(fin(λ))) = premier(fin(λ)) = b</code>. a serait <code>contenu(tête(λ))</code>, sans <code>succ</code>.', ref: C2 + '#s2' },
    { id: 'taa-c2-06', topic: 'taa-liste-rec', lvl: 1, type: 'single', q: 'Le profil de <code>cons</code> est <code>élément × liste → liste</code>. Lequel de ces termes est bien formé ?',
      o: ['<code>cons(a, cons(b, listevide))</code>', '<code>cons(listevide, a)</code>', '<code>cons(a, b)</code>', '<code>cons(a)</code>'], a: 0,
      x: 'Il faut un élément puis une liste. <code>cons(listevide, a)</code> inverse les arguments, <code>cons(a, b)</code> met un élément là où il faut une liste, et <code>cons(a)</code> oublie la liste. Même la liste à un élément s’écrit avec <code>listevide</code> : <code>cons(b, listevide)</code>.', ref: C2 + '#s2' },
    { id: 'taa-c2-07', topic: 'taa-liste-rec', lvl: 1, type: 'single', q: 'Une liste récursive est…',
      o: ['soit vide (<code>listevide</code>), soit un élément suivi d’une liste (<code>cons(e, λ)</code>)', 'un ensemble d’éléments numérotés à partir de 1', 'soit vide, soit réduite à un seul élément', 'une suite de places sans éléments'], a: 0,
      x: 'C’est une définition récursive : une liste non vide contient une liste plus petite, sa fin. Les rangs numérotés, c’est la liste itérative. Un élément seul s’écrit <code>cons(e, listevide)</code> : c’est un cas particulier de la deuxième forme.', ref: C2 + '#s2' },
    { id: 'taa-c2-08', topic: 'taa-liste-rec', lvl: 1, type: 'single', q: 'Quelles sont les deux façons de décrire une liste dans le cours ?',
      o: ['récursivement et itérativement', 'en pile et en file', 'avec ou sans places', 'triée ou non triée'], a: 0,
      x: 'Une liste se décrit soit récursivement (<code>listevide</code>, <code>cons</code>, <code>fin</code>, <code>premier</code>), soit itérativement, par le rang (<code>ième</code>, <code>longueur</code>, <code>insérer</code>, <code>supprimer</code>). Piles et files sont d’autres types.', ref: C2 + '#s8' },
    { id: 'taa-c2-09', topic: 'taa-liste-rec', lvl: 2, type: 'tf', a: false, q: 'Une liste récursive et une liste itérative sont deux données différentes : on ne peut pas décrire la même liste des deux façons.',
      x: 'Faux. C’est la même donnée, seule la manière de s’en servir change. λ = {e1, e2, e3} s’écrit <code>cons(e1, cons(e2, cons(e3, listevide)))</code> en récursif ; en itératif, elle est décrite par <code>longueur(λ) = 3</code>, <code>ième(λ, 1) = e1</code>, <code>ième(λ, 2) = e2</code> et <code>ième(λ, 3) = e3</code>.', ref: C2 + '#s8' },
    { id: 'taa-c2-10', topic: 'taa-liste-rec', lvl: 2, type: 'single', q: 'On définit <code>longueur : liste → entier</code> sur la liste récursive par deux axiomes. Le premier est <code>longueur(listevide) = 0</code>. Quel est le second ?',
      o: ['<code>longueur(cons(e, λ)) = longueur(λ) + 1</code>', '<code>longueur(cons(e, λ)) = 1</code>', '<code>longueur(cons(e, λ)) = longueur(λ)</code>', '<code>longueur(cons(e, λ)) = longueur(fin(λ)) + 1</code>'], a: 0,
      x: 'On traite les deux formes possibles d’une liste : <code>listevide</code> et <code>cons(e, λ)</code>. <code>cons(e, λ)</code> a un élément de plus que λ. « = 1 » ne vaut que si λ est vide. La dernière proposition compte un élément de moins, et utilise <code>fin(λ)</code>, qui n’est pas défini si λ est vide.', ref: C2 + '#s4' },
    { id: 'taa-c2-11', topic: 'taa-liste-rec', lvl: 2, type: 'single', q: 'Avec ces axiomes, que vaut <code>concaténer(cons(a, cons(b, listevide)), cons(c, listevide))</code> ?', fig: CONCAT,
      o: ['<code>cons(a, cons(b, cons(c, listevide)))</code>', '<code>cons(c, cons(a, cons(b, listevide)))</code>', '<code>cons(b, cons(a, cons(c, listevide)))</code>', '<code>cons(a, cons(b, listevide))</code>'], a: 0,
      x: 'Le second axiome sort la tête a, puis b : on obtient <code>cons(a, cons(b, concaténer(listevide, cons(c, listevide))))</code>. Le premier axiome termine : <code>concaténer(listevide, cons(c, listevide)) = cons(c, listevide)</code>. Les éléments de la première liste restent devant, dans leur ordre.', ref: C2 + '#s4' },
    { id: 'taa-c2-12', topic: 'taa-liste-rec', lvl: 3, type: 'single', q: 'Pour définir <code>est-présent</code> sur la liste récursive, il manque un axiome (à la place des ???). Lequel ?', fig: PRESENT,
      o: ['<code>e ≠ e′ ⇒ est-présent(e, cons(e′, λ)) = est-présent(e, λ)</code>', '<code>e ≠ e′ ⇒ est-présent(e, cons(e′, λ)) = faux</code>', '<code>est-présent(e, cons(e′, λ)) = est-présent(e, λ)</code>', '<code>e ≠ e′ ⇒ est-présent(e′, λ) = vrai</code>'], a: 0,
      x: 'Si la tête n’est pas e, e peut encore se trouver plus loin : on continue la recherche dans λ. Répondre faux arrête la recherche à la première tête différente. Sans la condition e ≠ e′, le troisième axiome contredirait le deuxième quand e = e′ et que e n’est pas dans λ (défaut de consistance).', ref: C2 + '#s4' },
    { id: 'taa-c2-13', topic: 'taa-liste-rec', lvl: 2, type: 'single', q: 'Avec ces axiomes, que vaut <code>dernier(cons(a, cons(b, cons(c, listevide))))</code> ?', fig: DERNIER,
      o: ['c', 'a', 'b', '<code>cons(c, listevide)</code>'], a: 0,
      x: 'Tant que la fin n’est pas vide, le second axiome retire la tête : <code>dernier(cons(b, cons(c, listevide)))</code>, puis <code>dernier(cons(c, listevide))</code>. Le premier axiome donne alors c. <code>dernier</code> renvoie un élément, pas une liste.', ref: C2 + '#s4' },
    { id: 'taa-c2-14', topic: 'taa-liste-rec', lvl: 3, type: 'single', q: 'Avec ces axiomes, que vaut <code>mystère(cons(a, cons(b, cons(a, cons(c, listevide)))), a)</code> ?', fig: MYST_REC,
      o: ['<code>cons(b, cons(c, listevide))</code>', '<code>cons(b, cons(a, cons(c, listevide)))</code>', '<code>cons(a, cons(a, listevide))</code>', '<code>cons(c, cons(b, listevide))</code>'], a: 0,
      x: 'Chaque tête égale à x est sautée, les autres sont gardées dans l’ordre : <code>mystère</code> supprime <em>toutes</em> les occurrences de x. Garder le deuxième a, c’est s’arrêter après la première suppression ; or le deuxième axiome continue avec <code>mystère(λ, x)</code>.', ref: C2 + '#s4' },
    { id: 'taa-c2-15', topic: 'taa-liste-rec', lvl: 3, type: 'single', q: 'λ est une liste récursive non vide. Que vaut <code>cons(premier(λ), fin(λ))</code> ?',
      o: ['λ', '<code>fin(λ)</code>', '<code>cons(premier(λ), λ)</code>', 'non défini'], a: 0,
      x: 'λ non vide s’écrit <code>cons(e, λ′)</code>. Alors <code>premier(λ) = e</code> et <code>fin(λ) = λ′</code> : on reconstruit <code>cons(e, λ′)</code>, c’est-à-dire λ. Le terme est défini parce que λ n’est pas vide : sinon ni <code>premier</code> ni <code>fin</code> ne le seraient.', ref: C2 + '#s3' },
    { id: 'taa-c2-16', topic: 'taa-liste-rec', lvl: 2, type: 'multi', q: 'Dans la liste récursive, quelles opérations ne sont définies que si λ ≠ listevide ?',
      o: ['<code>fin(λ)</code>', '<code>tête(λ)</code>', '<code>premier(λ)</code>', '<code>cons(e, λ)</code>'], a: [0, 1, 2],
      x: 'Ce sont les trois préconditions du cours : <code>fin</code>, <code>tête</code> et <code>premier</code> demandent λ ≠ listevide, car elles parlent de l’élément de tête. <code>cons(e, listevide)</code> est parfaitement défini : c’est la liste à un élément.', ref: C2 + '#s2' },

    /* ---------- préconditions des listes ---------- */
    { id: 'taa-c2-17', topic: 'taa-precond', lvl: 1, type: 'single', q: 'Dans une liste récursive, que vaut <code>fin(listevide)</code> ?',
      o: ['rien : ce terme n’est pas défini', '<code>listevide</code>', '0', 'faux'], a: 0,
      x: '<code>fin(λ) est-défini-ssi λ ≠ listevide</code>. Le piège : croire que la fin d’une liste vide est encore la liste vide. Il n’y a pas d’élément de tête à retirer, donc pas de résultat. 0 et faux ne sont même pas des listes.', ref: C2 + '#s2' },
    { id: 'taa-c2-18', topic: 'taa-precond', lvl: 2, type: 'num', a: 4, q: 'λ est une liste itérative de longueur 3. Pour combien de valeurs de k le terme <code>insérer(λ, k, e)</code> est-il défini ?',
      x: '<code>insérer(λ, k, e) est-défini-ssi 1 ≤ k ≤ longueur(λ) + 1</code>, soit k de 1 à 4. Le rang 4 place e après le dernier élément. Répondre 3, c’est recopier la précondition de <code>supprimer</code> (1 ≤ k ≤ longueur(λ)).', ref: C2 + '#s6' },
    { id: 'taa-c2-19', topic: 'taa-precond', lvl: 2, type: 'multi', q: 'λ = {a, b, c} est une liste itérative. Quels termes sont définis ?',
      o: ['<code>supprimer(λ, 3)</code>', '<code>insérer(λ, 4, d)</code>', '<code>supprimer(λ, 4)</code>', '<code>insérer(λ, 0, d)</code>', '<code>accès(λ, 0)</code>'], a: [0, 1],
      x: '<code>supprimer</code> et <code>accès</code> demandent 1 ≤ k ≤ longueur(λ) = 3 ; <code>insérer</code> accepte 1 ≤ k ≤ 4. Le rang 0 n’existe jamais : les rangs commencent à 1.', ref: C2 + '#s6' },
    { id: 'taa-c2-20', topic: 'taa-precond', lvl: 2, type: 'tf', a: true, q: 'Le terme <code>insérer(listevide, 1, a)</code> est défini.',
      x: 'Vrai. La précondition de <code>insérer</code> est seulement 1 ≤ k ≤ longueur(λ) + 1, sans condition λ ≠ listevide. Avec <code>longueur(listevide) = 0</code>, k = 1 convient : c’est ainsi qu’on place le premier élément. Pour <code>supprimer</code> et <code>accès</code>, au contraire, il faut λ ≠ listevide.', ref: C2 + '#s6' },
    { id: 'taa-c2-21', topic: 'taa-precond', lvl: 3, type: 'single', q: 'λ = {a, b, c} est une liste itérative. Lequel de ces termes n’est <em>pas</em> défini ?',
      o: ['<code>supprimer(supprimer(λ, 1), 3)</code>', '<code>supprimer(insérer(λ, 4, d), 4)</code>', '<code>insérer(supprimer(λ, 3), 3, d)</code>', '<code>insérer(λ, 1, d)</code>'], a: 0,
      x: 'Après <code>supprimer(λ, 1)</code>, la liste n’a plus que 2 éléments : le rang 3 n’existe plus. Une précondition se vérifie sur la liste à laquelle on applique l’opération, pas sur λ. <code>insérer(λ, 4, d)</code> a 4 éléments, on peut supprimer le 4e ; <code>supprimer(λ, 3)</code> en a 2, on peut insérer au rang 3 = 2 + 1.', ref: C2 + '#s6' },
    { id: 'taa-c2-22', topic: 'taa-precond', lvl: 3, type: 'single', q: 'On ajoute à la liste itérative <code>modifier : liste × entier × élément → liste</code> : <code>modifier(λ, k, e)</code> remplace le k-ième élément de λ par e. Quelle précondition donne son domaine exact ?',
      o: ['<code>modifier(λ, k, e) est-défini-ssi λ ≠ listevide &amp; 1 ≤ k ≤ longueur(λ)</code>', '<code>modifier(λ, k, e) est-défini-ssi 1 ≤ k ≤ longueur(λ) + 1</code>', '<code>modifier(λ, k, e) est-défini-ssi λ ≠ listevide</code>', '<code>modifier(λ, k, e) est-défini-ssi 0 ≤ k ≤ longueur(λ)</code>'], a: 0,
      x: 'On ne peut remplacer qu’un élément qui existe : c’est le domaine de <code>supprimer</code>. Le « + 1 » de <code>insérer</code> sert à ajouter après le dernier élément, ce qui n’a pas de sens pour un remplacement. Sans condition sur k, on accepterait k = 10 dans une liste de 3 éléments ; et le rang 0 n’existe pas.', ref: C2 + '#s6' },

    /* ---------- listes itératives ---------- */
    { id: 'taa-c2-23', topic: 'taa-liste-iter', lvl: 1, type: 'single', q: 'λ = {10, 20, 30} est une liste itérative. Que vaut <code>ième(λ, 1)</code> ?',
      o: ['10', '20', '1', 'non défini : les rangs commencent à 0'], a: 0,
      x: 'Les rangs commencent à 1 : <code>ième(λ, 1)</code> est le premier élément, 10. 20 serait la réponse avec des rangs comptés à partir de 0. Et <code>ième</code> renvoie un élément, pas un rang.', ref: C2 + '#s5' },
    { id: 'taa-c2-24', topic: 'taa-liste-iter', lvl: 2, type: 'single', q: 'λ = {a, b, c, d}. Que vaut <code>ième(insérer(λ, 2, x), 3)</code> ?',
      o: ['b', 'c', 'x', 'a'], a: 0,
      x: 'k = 2 &lt; i = 3 ≤ longueur(λ) + 1 = 5 : c’est le dernier axiome, <code>ième(insérer(λ, k, e), i) = ième(λ, i − 1)</code>, donc <code>ième(λ, 2) = b</code>. La nouvelle liste est {a, x, b, c, d} : tout ce qui suit x a été décalé d’un rang. Répondre c, c’est oublier ce décalage.', ref: C2 + '#s6' },
    { id: 'taa-c2-25', topic: 'taa-liste-iter', lvl: 2, type: 'single', q: 'λ = {a, b, c, d}. Que vaut <code>ième(supprimer(λ, 2), 2)</code> ?',
      o: ['c', 'b', 'a', 'd'], a: 0,
      x: 'k = 2 ≤ i = 2 ≤ longueur(λ) − 1 = 3 : <code>ième(supprimer(λ, k), i) = ième(λ, i + 1)</code>, soit <code>ième(λ, 3) = c</code>. La liste devient {a, c, d} : les éléments placés après le rang supprimé remontent d’un rang. b est justement l’élément supprimé.', ref: C2 + '#s6' },
    { id: 'taa-c2-26', topic: 'taa-liste-iter', lvl: 2, type: 'single', q: 'λ = {a, b, c, d}. Que vaut <code>ième(supprimer(λ, 3), 2)</code> ?',
      o: ['b', 'c', 'a', 'd'], a: 0,
      x: 'i = 2 &lt; k = 3 : c’est le cas <code>1 ≤ i &lt; k ⇒ ième(supprimer(λ, k), i) = ième(λ, i)</code>. Les éléments placés avant le rang supprimé ne bougent pas : <code>ième(λ, 2) = b</code>. Répondre c, c’est appliquer le décalage hors de sa condition.', ref: C2 + '#s6' },
    { id: 'taa-c2-27', topic: 'taa-liste-iter', lvl: 3, type: 'single', q: 'λ = {a, b, c}. Que vaut <code>ième(supprimer(insérer(λ, 1, x), 3), 2)</code> ?',
      o: ['a', 'b', 'x', 'c'], a: 0,
      x: '<code>insérer(λ, 1, x)</code> donne {x, a, b, c}. Supprimer le rang 3 retire b : {x, a, c}, dont le rang 2 contient a. Avec les axiomes : i = 2 &lt; k = 3 donne <code>ième(insérer(λ, 1, x), 2)</code>, puis 1 &lt; 2 donne <code>ième(λ, 1) = a</code>.', ref: C2 + '#s6' },
    { id: 'taa-c2-28', topic: 'taa-liste-iter', lvl: 3, type: 'single', q: 'λ = {10, 20, 30, 40, 50}. Que vaut <code>ième(insérer(supprimer(λ, 1), 3, 99), 4)</code> ?',
      o: ['40', '50', '30', '99'], a: 0,
      x: '<code>supprimer(λ, 1)</code> donne {20, 30, 40, 50}. Insérer 99 au rang 3 donne {20, 30, 99, 40, 50}, dont le rang 4 contient 40. Les deux décalages se compensent pour 40 : il remonte d’un rang, puis redescend d’un rang.', ref: C2 + '#s6' },
    { id: 'taa-c2-29', topic: 'taa-liste-iter', lvl: 2, type: 'num', a: 5, q: 'λ = {a, b, c}. Que vaut <code>longueur(insérer(insérer(λ, 1, x), 5, y))</code> ?',
      x: 'Après la première insertion, la liste a 4 éléments : le rang 5 = 4 + 1 est permis, et y se place à la fin. Deux insertions : 3 + 2 = 5. La précondition se vérifie sur la liste intermédiaire, pas sur λ.', ref: C2 + '#s6' },
    { id: 'taa-c2-30', topic: 'taa-liste-iter', lvl: 2, type: 'single', q: 'λ = {a, b, c, d} et p2 = <code>accès(λ, 2)</code>. Que vaut <code>contenu(succ(p2))</code> ?',
      o: ['c', 'b', 'd', 'non défini : <code>succ</code> renvoie un entier'], a: 0,
      x: '<code>succ(accès(λ, k)) = accès(λ, k + 1)</code> : <code>succ(p2)</code> est la place du 3e élément. Puis <code>contenu(accès(λ, 3)) = ième(λ, 3) = c</code>. C’est l’exemple de l’erratum de la vidéo : <code>succ : place → place</code> passe à la place suivante. b est le contenu de p2 lui-même.', ref: C2 + '#s5' },
    { id: 'taa-c2-31', topic: 'taa-liste-iter', lvl: 2, type: 'multi', q: 'λ = {a, b, c} est une liste itérative. Quels termes valent b ?',
      o: ['<code>ième(λ, 2)</code>', '<code>contenu(accès(λ, 2))</code>', '<code>contenu(succ(accès(λ, 1)))</code>', '<code>contenu(succ(accès(λ, 2)))</code>', '<code>ième(λ, 1)</code>'], a: [0, 1, 2],
      x: '<code>contenu(accès(λ, k)) = ième(λ, k)</code> : la place du rang 2 contient b. <code>succ(accès(λ, 1)) = accès(λ, 2)</code>, donc le troisième terme vaut aussi b. <code>succ(accès(λ, 2))</code> est la place du rang 3, qui contient c ; et <code>ième(λ, 1) = a</code>.', ref: C2 + '#s5' },
    { id: 'taa-c2-32', topic: 'taa-liste-iter', lvl: 2, type: 'single', q: 'Quel terme construit la liste {a, b} à partir de <code>listevide</code> ?',
      o: ['<code>insérer(insérer(listevide, 1, b), 1, a)</code>', '<code>insérer(insérer(listevide, 1, a), 1, b)</code>', '<code>insérer(insérer(listevide, 1, a), 3, b)</code>', '<code>insérer(listevide, 1, a, b)</code>'], a: 0,
      x: 'On place b, puis on insère a au rang 1, devant b : {a, b}. Le deuxième terme donne {b, a}, car b est inséré devant a. Le troisième n’est pas défini : la liste {a} n’accepte que les rangs 1 et 2. Le dernier ne respecte pas le profil de <code>insérer</code> (trois arguments).', ref: C2 + '#s6' },
    { id: 'taa-c2-33', topic: 'taa-liste-iter', lvl: 2, type: 'single', q: 'Dans l’axiome <code>k &lt; i ≤ longueur(λ) + 1 ⇒ ième(insérer(λ, k, e), i) = ième(λ, i − 1)</code>, pourquoi i peut-il aller jusqu’à longueur(λ) + 1 ?',
      o: ['la liste obtenue a un élément de plus : son dernier rang est longueur(λ) + 1', 'pour pouvoir lire un rang qui n’existe pas', 'c’est une coquille : il faut longueur(λ)', 'pour inclure le rang 0'], a: 0,
      x: 'Après l’insertion, la liste a longueur(λ) + 1 éléments. Son dernier rang est donc longueur(λ) + 1, et il contient l’ancien dernier élément de λ, <code>ième(λ, longueur(λ))</code>. Avec longueur(λ) comme borne, ce dernier élément ne serait plus décrit (défaut de complétude).', ref: C2 + '#s6' },
    { id: 'taa-c2-34', topic: 'taa-liste-iter', lvl: 3, type: 'single', q: 'Une erreur s’est glissée dans ces axiomes de <code>insérer</code>. Laquelle ?', fig: INS_FAUX,
      o: ['le deuxième axiome doit s’arrêter à i &lt; k : pour i = k, il contredit le troisième', 'le troisième axiome est en trop', 'le quatrième doit lire <code>ième(λ, i + 1)</code>', 'la longueur doit rester <code>longueur(λ)</code>'], a: 0,
      x: 'Pour i = k, le deuxième axiome donne <code>ième(λ, k)</code> et le troisième donne e : deux valeurs pour un même terme, c’est un défaut de consistance. Le cours écrit <code>1 ≤ i &lt; k</code>. Les autres axiomes sont ceux du cours : après le rang k, on lit l’élément du rang précédent, i − 1, et une insertion ajoute un élément.', ref: C2 + '#s6' },
    { id: 'taa-c2-35', topic: 'taa-liste-iter', lvl: 3, type: 'single', q: 'Pour <code>modifier(λ, k, e)</code>, qui remplace le k-ième élément par e, on a déjà <code>longueur(modifier(λ, k, e)) = longueur(λ)</code> et <code>i = k ⇒ ième(modifier(λ, k, e), i) = e</code>. Quel axiome complète la spécification ?',
      o: ['<code>1 ≤ i ≤ longueur(λ) &amp; i ≠ k ⇒ ième(modifier(λ, k, e), i) = ième(λ, i)</code>', '<code>i ≠ k ⇒ ième(modifier(λ, k, e), i) = e</code>', '<code>ième(modifier(λ, k, e), i) = ième(λ, i)</code>', '<code>1 ≤ i ≤ longueur(λ) &amp; i ≠ k ⇒ ième(modifier(λ, k, e), i) = ième(λ, i + 1)</code>'], a: 0,
      x: 'Les autres rangs gardent leur élément. Sans la condition i ≠ k, le troisième axiome contredirait <code>i = k ⇒ … = e</code> (défaut de consistance). Le deuxième remplirait toute la liste de e. Le dernier décale les éléments comme <code>supprimer</code>, alors que <code>modifier</code> ne change aucun rang.', ref: C2 + '#s6' },
    { id: 'taa-c2-36', topic: 'taa-liste-iter', lvl: 2, type: 'single', q: 'λ = {a, b, c, d}. Avec ces axiomes, que vaut <code>mystère(λ)</code> ?', fig: MYST_INV,
      o: ['<code>{d, c, b, a}</code>', '<code>{a, b, c, d}</code>', '<code>{b, c, d, a}</code>', '<code>{d, a, b, c}</code>'], a: 0,
      x: 'La longueur ne change pas. Pour i = 1, on lit le rang 4 − 1 + 1 = 4 (d) ; pour i = 2, le rang 3 (c) ; puis le rang 2 (b) et le rang 1 (a) : <code>mystère</code> renverse la liste. Calcule toujours deux ou trois rangs à la main avant de reconnaître l’opération.', ref: C2 + '#s7' },
    { id: 'taa-c2-37', topic: 'taa-liste-iter', lvl: 2, type: 'single', q: 'λ = {10, 20, 30, 40}. Avec ces axiomes, que vaut <code>mystère(λ)</code> ?', fig: MYST_ROT,
      o: ['<code>{20, 30, 40, 10}</code>', '<code>{40, 10, 20, 30}</code>', '<code>{40, 30, 20, 10}</code>', '<code>{20, 30, 40}</code>'], a: 0,
      x: 'Pour i de 1 à 3, on lit le rang suivant : 20, 30, 40. Le dernier rang reçoit le premier élément, 10. <code>mystère</code> fait tourner la liste d’un cran vers la gauche. {40, 10, 20, 30} serait une rotation dans l’autre sens ; {20, 30, 40} oublie que la longueur ne change pas.', ref: C2 + '#s7' },
    { id: 'taa-c2-38', topic: 'taa-liste-iter', lvl: 3, type: 'single', q: 'λ = {10, 20, 30, 40, 50}. Avec ces axiomes, que vaut <code>mystère(λ, 2, 4)</code> ?', fig: MYST_ECH,
      o: ['<code>{10, 40, 30, 20, 50}</code>', '<code>{10, 20, 30, 40, 50}</code>', '<code>{10, 30, 40, 20, 50}</code>', '<code>{10, 20, 50, 40, 30}</code>'], a: 0,
      x: 'Au rang x = 2, on lit l’ancien rang y = 4 (40) ; au rang y = 4, l’ancien rang x = 2 (20). Les autres rangs ne bougent pas : <code>mystère</code> échange deux éléments. {10, 20, 50, 40, 30} échange les rangs 3 et 5 : un décalage d’indice. Si x = y, les deux premiers axiomes de <code>ième</code> donnent la même valeur : ils ne se contredisent pas.', ref: C2 + '#s7' },
    { id: 'taa-c2-39', topic: 'taa-liste-iter', lvl: 2, type: 'num', a: 6, q: 'λ est une liste de longueur 9. Avec ces axiomes, que vaut <code>longueur(mystère(λ, 3, 5))</code> ?', fig: MYST_SUP,
      x: 'L’axiome de longueur donne 9 − 5 + 3 − 1 = 6. Les rangs 1 et 2 sont gardés, puis le rang 3 lit l’ancien rang 3 + 5 − 3 + 1 = 6 : les rangs 3 à 5 ont disparu. <code>mystère</code> supprime les éléments des rangs x à y, soit y − x + 1 = 3 éléments.', ref: C2 + '#s7' },
    { id: 'taa-c2-40', topic: 'taa-liste-iter', lvl: 3, type: 'single', q: 'λ = {2, 4, 6, 8, 10, 12, 14}. Avec ces axiomes, que vaut <code>mystère(λ, 2, 4)</code> ?', fig: MYST_SUP,
      o: ['<code>{2, 10, 12, 14}</code>', '<code>{4, 6, 8}</code>', '<code>{2, 12, 14}</code>', '<code>{2, 4, 10, 12, 14}</code>'], a: 0,
      x: 'Longueur : 7 − 4 + 2 − 1 = 4. Le rang 1 ne bouge pas (1 &lt; x = 2) : 2. Pour i de 2 à 4, on lit l’ancien rang i + 4 − 2 + 1 = i + 3, soit les rangs 5, 6 et 7 : 10, 12, 14. Les rangs 2 à 4 (4, 6, 8) ont été supprimés ; {4, 6, 8} est ce qu’on a retiré, pas ce qui reste.', ref: C2 + '#s7' },
    { id: 'taa-c2-41', topic: 'taa-liste-iter', lvl: 2, type: 'single', q: 'Avec ces axiomes, à quel terme <code>mystère(λ, e)</code> est-il égal ?', fig: MYST_FIN,
      o: ['<code>insérer(λ, longueur(λ) + 1, e)</code>', '<code>insérer(λ, 1, e)</code>', '<code>insérer(λ, longueur(λ), e)</code>', '<code>supprimer(λ, longueur(λ))</code>'], a: 0,
      x: 'Un élément de plus, les anciens rangs inchangés, et e au dernier rang : <code>mystère</code> ajoute e en fin de liste. C’est l’insertion au rang longueur(λ) + 1. Au rang longueur(λ), e passerait avant l’ancien dernier élément ; au rang 1, devant tous les autres.', ref: C2 + '#s7' },

    /* ================= chapitre 3 : piles, files, ensembles ================= */
    /* ---------- piles ---------- */
    { id: 'taa-c3-01', topic: 'taa-piles', lvl: 1, type: 'single', q: 'Une pile est une structure…',
      o: ['LIFO : le dernier élément entré est le premier sorti', 'FIFO : le premier élément entré est le premier sorti', 'où l’on accède à chaque élément par son rang', 'sans ordre, comme un ensemble'], a: 0,
      x: 'Last In First Out : les entrées et les sorties se font du même côté, le sommet. FIFO, c’est la file. L’accès par le rang, c’est la liste itérative.', ref: C3 + '#s1' },
    { id: 'taa-c3-02', topic: 'taa-piles', lvl: 1, type: 'single', q: 'Que vaut <code>sommet(empiler(empiler(empiler(pilevide, a), b), c))</code> ?',
      o: ['c', 'a', 'b', '<code>empiler(pilevide, c)</code>'], a: 0,
      x: '<code>sommet(empiler(p, e)) = e</code> : le sommet est le dernier élément empilé, celui de l’<code>empiler</code> le plus extérieur. Répondre a, c’est raisonner comme une file. Et <code>sommet</code> renvoie un élément, pas une pile.', ref: C3 + '#s3' },
    { id: 'taa-c3-03', topic: 'taa-piles', lvl: 2, type: 'single', q: 'Que vaut <code>sommet(dépiler(empiler(empiler(pilevide, a), b)))</code> ?',
      o: ['a', 'b', 'non défini', '<code>empiler(pilevide, a)</code>'], a: 0,
      x: '<code>dépiler(empiler(p, e)) = p</code> : <code>dépiler(empiler(empiler(pilevide, a), b)) = empiler(pilevide, a)</code>. Puis <code>sommet(empiler(pilevide, a)) = a</code>. b vient d’être dépilé.', ref: C3 + '#s3' },
    { id: 'taa-c3-04', topic: 'taa-piles', lvl: 2, type: 'single', q: 'Que vaut <code>estvide(dépiler(dépiler(empiler(empiler(pilevide, a), b))))</code> ?',
      o: ['vrai', 'faux', 'non défini', '<code>pilevide</code>'], a: 0,
      x: 'Les deux <code>dépiler</code> annulent les deux <code>empiler</code> : on revient à <code>pilevide</code>, et <code>estvide(pilevide) = vrai</code>. Chaque <code>dépiler</code> s’applique à une pile non vide, donc tout est défini. <code>estvide</code> renvoie un booléen, pas une pile.', ref: C3 + '#s3' },
    { id: 'taa-c3-05', topic: 'taa-piles', lvl: 2, type: 'single', q: 'Que vaut <code>sommet(dépiler(empiler(pilevide, a)))</code> ?',
      o: ['non défini', 'a', '<code>pilevide</code>', 'faux'], a: 0,
      x: '<code>dépiler(empiler(pilevide, a)) = pilevide</code>. Il reste <code>sommet(pilevide)</code> : la précondition <code>estvide(p) = faux</code> n’est pas respectée, le terme n’a pas de valeur. Ce n’est pas faux pour autant : <code>sommet</code> renvoie un élément, jamais un booléen.', ref: C3 + '#s3' },
    { id: 'taa-c3-06', topic: 'taa-piles', lvl: 3, type: 'single', q: 'Sur une pile vide, on empile a, puis b, puis c ; on dépile deux fois ; puis on empile d. Quelle pile obtient-on ?',
      o: ['<code>empiler(empiler(pilevide, a), d)</code>', '<code>empiler(empiler(pilevide, c), d)</code>', '<code>empiler(empiler(pilevide, d), a)</code>', '<code>empiler(pilevide, d)</code>'], a: 0,
      x: 'Chaque <code>dépiler</code> retire le dernier élément empilé : c, puis b. Il reste a, sur lequel on empile d. Le deuxième choix retire les deux premiers entrés, comme une file. Dans le terme, le sommet est l’élément de l’<code>empiler</code> le plus extérieur.', ref: C3 + '#s3' },
    { id: 'taa-c3-07', topic: 'taa-piles', lvl: 1, type: 'multi', q: 'À quoi sert une pile ?',
      o: ['inverser l’ordre des éléments', 'évaluer des expressions', 'simuler la pile des appels (rendre itératif un algorithme récursif)', 'conserver l’ordre d’arrivée, comme une file d’attente', 'parcourir un arbre en largeur'], a: [0, 1, 2],
      x: 'Ce sont les trois usages donnés par le cours. Conserver l’ordre d’arrivée (buffers, files d’attente) et parcourir en largeur, ce sont des usages de la file.', ref: C3 + '#s1' },
    { id: 'taa-c3-08', topic: 'taa-piles', lvl: 2, type: 'single', q: 'On empile a, b, c sur une pile vide, puis on dépile jusqu’à la vider, en notant chaque sommet juste avant de le dépiler. Dans quel ordre les éléments sont-ils notés ?',
      o: ['c, b, a', 'a, b, c', 'c, a, b', 'b, c, a'], a: 0,
      x: 'Le dernier entré sort le premier : c, puis b, puis a. C’est pour cela qu’une pile sert à inverser l’ordre des éléments.', ref: C3 + '#s1' },
    { id: 'taa-c3-09', topic: 'taa-piles', lvl: 2, type: 'tf', a: true, q: 'L’axiome <code>dépiler(empiler(p, e)) = p</code> vaut aussi quand p est la pile vide.',
      x: 'Vrai. L’axiome n’a aucune condition : <code>dépiler(empiler(pilevide, e)) = pilevide</code>. La précondition de <code>dépiler</code> porte sur <code>empiler(p, e)</code>, qui n’est jamais vide, pas sur p.', ref: C3 + '#s2' },
    { id: 'taa-c3-10', topic: 'taa-piles', lvl: 3, type: 'single', q: 'Que vaut <code>sommet(empiler(dépiler(empiler(empiler(pilevide, a), b)), sommet(empiler(pilevide, c))))</code> ?',
      o: ['c', 'a', 'b', 'non défini'], a: 0,
      x: 'On calcule d’abord les arguments : <code>dépiler(empiler(empiler(pilevide, a), b)) = empiler(pilevide, a)</code> et <code>sommet(empiler(pilevide, c)) = c</code>. Le terme devient <code>sommet(empiler(empiler(pilevide, a), c))</code>, qui vaut c, le dernier élément empilé.', ref: C3 + '#s3' },
    { id: 'taa-c3-11', topic: 'taa-piles', lvl: 2, type: 'num', a: 1, q: 'Combien d’éléments contient la pile <code>dépiler(empiler(dépiler(empiler(empiler(pilevide, a), b)), c))</code> ?',
      x: 'De l’intérieur vers l’extérieur : on empile a et b, on dépile b, on empile c, on dépile c. Il reste a. Avec l’axiome <code>dépiler(empiler(p, e)) = p</code> appliqué deux fois, on obtient <code>empiler(pilevide, a)</code>.', ref: C3 + '#s3' },
    { id: 'taa-c3-12', topic: 'taa-precond', lvl: 2, type: 'multi', q: 'Dans le type pile, quelles opérations ont une précondition ?',
      o: ['<code>dépiler</code>', '<code>sommet</code>', '<code>empiler</code>', '<code>estvide</code>', '<code>pilevide</code>'], a: [0, 1],
      x: '<code>dépiler</code> et <code>sommet</code> sont partielles : sur une pile vide, il n’y a rien à enlever ni à lire. On peut toujours empiler, <code>estvide</code> répond pour toute pile, et <code>pilevide</code> n’a pas d’argument.', ref: C3 + '#s2' },
    { id: 'taa-c3-13', topic: 'taa-axiomes', lvl: 2, type: 'single', q: 'Un seul de ces axiomes de la pile est faux. Lequel ?',
      o: ['<code>dépiler(empiler(p, e)) = e</code>', '<code>sommet(empiler(p, e)) = e</code>', '<code>estvide(pilevide) = vrai</code>', '<code>estvide(empiler(p, e)) = faux</code>'], a: 0,
      x: '<code>dépiler</code> renvoie une pile : le bon axiome est <code>dépiler(empiler(p, e)) = p</code>. Écrire « = e » égale une pile et un élément, ce qui n’a pas de sens : les deux membres d’un axiome sont du même type. C’est <code>sommet</code> qui renvoie e.', ref: C3 + '#s2' },
    { id: 'taa-c3-14', topic: 'taa-axiomes', lvl: 3, type: 'single', q: '<code>sommet</code> est partielle, pourtant l’axiome <code>sommet(empiler(p, e)) = e</code> n’a aucune condition. Pourquoi ?',
      o: ['<code>empiler(p, e)</code> n’est jamais vide, donc la précondition de <code>sommet</code> est toujours respectée', 'parce que <code>sommet</code> est un observateur', 'il en faudrait une : <code>estvide(p) = faux ⇒</code>', 'parce que les axiomes ne tiennent jamais compte des préconditions'], a: 0,
      x: '<code>estvide(empiler(p, e)) = faux</code> pour toute pile p : on peut toujours lire le sommet d’une pile qu’on vient de remplir. Ajouter <code>estvide(p) = faux ⇒</code> ferait perdre le cas p = pilevide, alors que <code>sommet(empiler(pilevide, e)) = e</code>. Être un observateur n’y est pour rien.', ref: C3 + '#s2' },

    /* ---------- files ---------- */
    { id: 'taa-c3-15', topic: 'taa-files', lvl: 1, type: 'single', q: 'Une file est une structure…',
      o: ['FIFO : le premier élément entré est le premier sorti', 'LIFO : le dernier élément entré est le premier sorti', 'où l’on accède à chaque élément par son rang', 'où l’on ajoute et retire du même côté'], a: 0,
      x: 'First In First Out, comme une file d’attente : on ajoute en queue (<code>enfiler</code>) et on retire en tête (<code>défiler</code>), aux deux extrémités. Entrer et sortir du même côté, c’est la pile (LIFO).', ref: C3 + '#s4' },
    { id: 'taa-c3-16', topic: 'taa-files', lvl: 1, type: 'single', q: 'Que vaut <code>premier(enfiler(enfiler(enfiler(filevide, a), b), c))</code> ?',
      o: ['a', 'c', 'b', 'non défini'], a: 0,
      x: 'Le premier d’une file est l’élément entré en premier, celui de l’<code>enfiler</code> le plus intérieur. Avec les axiomes : la file sous c n’est pas vide, donc <code>premier(enfiler(f, c)) = premier(f)</code> ; on descend ainsi jusqu’à <code>premier(enfiler(filevide, a)) = a</code>. Répondre c, c’est raisonner comme une pile.', ref: C3 + '#s6' },
    { id: 'taa-c3-17', topic: 'taa-files', lvl: 2, type: 'single', q: 'Que vaut <code>premier(défiler(enfiler(enfiler(filevide, a), b)))</code> ?',
      o: ['b', 'a', 'non défini', '<code>enfiler(filevide, b)</code>'], a: 0,
      x: 'La file sous b, <code>enfiler(filevide, a)</code>, n’est pas vide : <code>défiler(enfiler(f, b)) = enfiler(défiler(f), b)</code>. Et <code>défiler(enfiler(filevide, a)) = filevide</code>. On obtient <code>enfiler(filevide, b)</code>, dont le premier est b. Défiler a retiré a, le premier entré.', ref: C3 + '#s6' },
    { id: 'taa-c3-18', topic: 'taa-files', lvl: 3, type: 'single', q: 'Que vaut <code>défiler(enfiler(enfiler(enfiler(filevide, a), b), c))</code> ?',
      o: ['<code>enfiler(enfiler(filevide, b), c)</code>', '<code>enfiler(enfiler(filevide, a), b)</code>', '<code>enfiler(enfiler(filevide, c), b)</code>', '<code>enfiler(filevide, c)</code>'], a: 0,
      x: 'Le dernier axiome fait descendre <code>défiler</code> sous les <code>enfiler</code> : <code>défiler(enfiler(f, c)) = enfiler(défiler(f), c)</code> tant que f n’est pas vide, jusqu’à <code>défiler(enfiler(filevide, a)) = filevide</code>. Il reste b puis c, dans l’ordre d’arrivée. Retirer c, c’est le comportement d’une pile.', ref: C3 + '#s6' },
    { id: 'taa-c3-19', topic: 'taa-files', lvl: 2, type: 'single', q: 'Pourquoi les axiomes qui donnent <code>premier(enfiler(f, e))</code> sont-ils conditionnels ?',
      o: ['le résultat dépend de f : si f est vide, e devient le premier ; sinon le premier reste celui de f', 'parce que <code>premier</code> est un observateur', 'parce que <code>enfiler</code> est une opération partielle', 'pour ne pas avoir à écrire les axiomes de <code>estvide</code>'], a: 0,
      x: 'On enfile en queue : le nouvel élément n’est le premier que si la file était vide. Il faut donc deux axiomes, l’un sous <code>estvide(f) = vrai</code>, l’autre sous <code>estvide(f) = faux</code>. <code>enfiler</code> est définie partout. Et <code>sommet</code>, observateur de la pile, n’a pas besoin de condition : être un observateur n’explique rien.', ref: C3 + '#s5' },
    { id: 'taa-c3-20', topic: 'taa-files', lvl: 2, type: 'tf', a: false, q: 'Pour toute file f, <code>défiler(enfiler(f, e)) = f</code>.',
      x: 'Faux : c’est l’axiome de la pile. Pour une file non vide, <code>défiler</code> retire le premier de f, pas e : <code>défiler(enfiler(f, e)) = enfiler(défiler(f), e)</code>. Par exemple <code>défiler(enfiler(enfiler(filevide, a), b)) = enfiler(filevide, b)</code>, qui n’est pas <code>enfiler(filevide, a)</code>.', ref: C3 + '#s5' },
    { id: 'taa-c3-21', topic: 'taa-files', lvl: 1, type: 'multi', q: 'À quoi sert une file ?',
      o: ['conserver l’ordre des éléments', 'gérer des buffers (imprimante, clavier)', 'parcourir en largeur un arbre ou un graphe', 'inverser l’ordre des éléments', 'simuler la pile des appels'], a: [0, 1, 2],
      x: 'Ce sont les usages donnés par le cours : une file rend les éléments dans leur ordre d’arrivée. Inverser l’ordre et simuler la pile des appels sont des usages de la pile.', ref: C3 + '#s4' },
    { id: 'taa-c3-22', topic: 'taa-files', lvl: 2, type: 'single', q: 'Sur une file vide, on enfile a, b, c ; on défile ; on enfile d ; on défile. Quelle file obtient-on ?',
      o: ['<code>enfiler(enfiler(filevide, c), d)</code>', '<code>enfiler(enfiler(filevide, a), b)</code>', '<code>enfiler(enfiler(filevide, d), c)</code>', '<code>enfiler(filevide, d)</code>'], a: 0,
      x: 'Chaque <code>défiler</code> retire le plus ancien : a, puis b. Il reste c puis d, dans l’ordre d’arrivée : c est le premier. Le deuxième choix est ce que donnerait une pile, qui retire c puis d.', ref: C3 + '#s6' },
    { id: 'taa-c3-23', topic: 'taa-files', lvl: 3, type: 'single', q: 'Que vaut <code>premier(enfiler(défiler(enfiler(enfiler(filevide, a), b)), c))</code> ?',
      o: ['b', 'c', 'a', 'non défini'], a: 0,
      x: '<code>défiler(enfiler(enfiler(filevide, a), b)) = enfiler(filevide, b)</code>. On enfile c derrière : <code>enfiler(enfiler(filevide, b), c)</code>. La file sous c n’est pas vide, donc le premier reste b.', ref: C3 + '#s6' },
    { id: 'taa-c3-24', topic: 'taa-files', lvl: 3, type: 'single', q: 'On fait la même chose sur une pile et sur une file, vides au départ : on ajoute a, puis b, puis c ; on retire un élément ; on lit l’élément accessible (<code>sommet</code> ou <code>premier</code>). Que lit-on ?',
      o: ['b avec la pile, b avec la file', 'b avec la pile, c avec la file', 'a avec la pile, c avec la file', 'c avec la pile, a avec la file'], a: 0,
      x: 'Pile : on retire c, le dernier entré ; il reste a, b et le sommet est b. File : on retire a, le premier entré ; il reste b, c et le premier est b. Même résultat pour deux raisons différentes : il faut faire le calcul, pas deviner.', ref: C3 + '#s6' },

    /* ---------- ensembles et multi-ensembles ---------- */
    { id: 'taa-c3-25', topic: 'taa-ensembles', lvl: 1, type: 'single', q: 'Pour un ensemble, qu’est-ce qui compte ?',
      o: ['qu’un élément soit présent ou non', 'l’ordre des éléments', 'le rang de chaque élément', 'le nombre de fois qu’un élément a été ajouté'], a: 0,
      x: 'Contrairement aux listes, l’ordre n’a aucune importance dans un ensemble : seule compte la présence d’un élément. Le nombre d’occurrences, c’est ce qui distingue les multi-ensembles.', ref: C3 + '#s7' },
    { id: 'taa-c3-26', topic: 'taa-ensembles', lvl: 2, type: 'num', a: 2, q: 'Que vaut <code>card(ajouter(a, ajouter(b, ajouter(a, ensemblevide))))</code> ?',
      x: 'De l’intérieur vers l’extérieur : a est absent de l’ensemble vide, card = 1 ; b est absent, card = 2 ; a est déjà présent, donc <code>x ∈ e = vrai ⇒ card(ajouter(x, e)) = card(e)</code> : on reste à 2. Ajouter un élément déjà présent est sans effet. 3, c’est la réponse pour un multi-ensemble.', ref: C3 + '#s7' },
    { id: 'taa-c3-27', topic: 'taa-ensembles', lvl: 2, type: 'single', q: 'Que vaut <code>b ∈ supprimer(b, ajouter(b, ajouter(b, ensemblevide)))</code> ?',
      o: ['faux', 'vrai', 'non défini', '1'], a: 0,
      x: 'L’axiome <code>x = y ⇒ (x ∈ supprimer(y, e)) = faux</code> conclut directement : après la suppression de b, b n’est plus dans l’ensemble. Ajouter b deux fois n’a mis qu’un b : un ensemble ne compte pas les occurrences.', ref: C3 + '#s7' },
    { id: 'taa-c3-28', topic: 'taa-ensembles', lvl: 2, type: 'num', a: 2, q: 'Que vaut <code>card(supprimer(c, ajouter(a, ajouter(b, ensemblevide))))</code> ?',
      x: 'c n’est pas dans l’ensemble : <code>x ∈ e = faux ⇒ card(supprimer(x, e)) = card(e)</code>. Supprimer un élément absent est sans effet, le cardinal reste 2. Le cours choisit ce comportement plutôt qu’une précondition.', ref: C3 + '#s7' },
    { id: 'taa-c3-29', topic: 'taa-ensembles', lvl: 2, type: 'single', q: 'Que garantit l’axiome <code>choisir(e) ∈ e = vrai</code> ?',
      o: ['l’élément choisi appartient à l’ensemble', 'l’élément choisi est le plus petit', 'l’élément choisi est le premier ajouté', 'l’élément choisi est retiré de l’ensemble'], a: 0,
      x: 'L’axiome dit seulement que l’élément renvoyé est dans e, pas lequel. Un ensemble n’a pas d’ordre : « le premier ajouté » n’a pas de sens. Et <code>choisir</code> renvoie un élément sans modifier e ; pour énumérer, on supprime ensuite l’élément traité.', ref: C3 + '#s7' },
    { id: 'taa-c3-30', topic: 'taa-ensembles', lvl: 2, type: 'multi', q: 'Dans le type ensemble, quelles opérations ont une précondition ?',
      o: ['<code>choisir</code>', '<code>supprimer</code>', '<code>ajouter</code>', '<code>card</code>', '<code>_∈_</code>'], a: [0],
      x: 'Seule <code>choisir</code> est partielle : <code>choisir(e) est-défini-ssi e ≠ ensemblevide</code>. Le cours rend <code>ajouter</code> et <code>supprimer</code> sans effet en cas d’erreur (élément déjà présent, élément absent) plutôt que partielles, et <code>card</code> est définie partout.', ref: C3 + '#s7' },
    { id: 'taa-c3-31', topic: 'taa-ensembles', lvl: 2, type: 'multi', q: 'e = <code>ajouter(a, ajouter(b, ensemblevide))</code>. Quels termes valent vrai ?',
      o: ['<code>a ∈ e</code>', '<code>b ∈ supprimer(a, e)</code>', '<code>a ∈ supprimer(a, e)</code>', '<code>c ∈ e</code>', '<code>choisir(e) ∈ e</code>'], a: [0, 1, 4],
      x: 'a vient d’être ajouté : <code>a ∈ e</code> vaut vrai. b ≠ a, donc supprimer a ne touche pas b. <code>a ∈ supprimer(a, e)</code> vaut faux, et c n’a jamais été ajouté. Enfin <code>choisir(e) ∈ e = vrai</code> est un axiome, et e n’est pas vide.', ref: C3 + '#s7' },
    { id: 'taa-c3-32', topic: 'taa-ensembles', lvl: 2, type: 'num', a: 3, q: 'Dans un multi-ensemble, que vaut <code>card(ajouter(a, ajouter(b, ajouter(a, multiensemblevide))))</code> ?',
      x: 'Pour un multi-ensemble, <code>card(ajouter(x, me)) = card(me) + 1</code>, sans condition : chaque ajout compte, même un doublon. Le même terme pour un ensemble donnerait 2.', ref: C3 + '#s8' },
    { id: 'taa-c3-33', topic: 'taa-ensembles', lvl: 3, type: 'num', a: 1, q: 'Que vaut <code>nboccurrences(a, supprimer(a, ajouter(b, ajouter(a, ajouter(a, multiensemblevide)))))</code> ?',
      x: 'Avant la suppression, a a été ajouté deux fois : <code>nboccurrences</code> vaut 2 (l’ajout de b ne compte pas pour a). Puis <code>nboccurrences(x, me) ≥ 1 ⇒ nboccurrences(x, supprimer(x, me)) = nboccurrences(x, me) − 1</code> : 2 − 1 = 1. Dans un multi-ensemble, supprimer ne retire qu’une occurrence.', ref: C3 + '#s8' }
  ];
  Q.forEach(function (q) { q.s = 'taa'; });
  Array.prototype.push.apply(B, Q);
})();
